import os
import shutil
import zipfile
import re
import PyPDF2
from collections import Counter

SOURCE_DIR = "/root/papers/all"
CATEGORIES = {
    "LLM": ["large language model", " llm", "transformer", "attention mechanism", "generative ai", "chatgpt", "gpt-3", "gpt-4", "bert", "roberta", "chain-of-thought", "prompt engineering", "natural language processing", " nlp", "token", "decoder-only"],
    "trapped_ion_and_qc": ["trapped ion", "ion trap", "quantum comput", "qubit", "quantum gate", "paul trap", "rabi", "hyperfine", "entangle", "fidelity", "quantum information", "coherence time", "motional state", "laser cooling", "sideband"],
    "black_hole": ["black hole", "event horizon", "gravitational wave", "schwarzschild", "kerr", "accretion", "quasar", "agn", "supermassive", "stellar mass", "general relativity", "hawking radiation", "singularity", "spacetim"],
    "DNA": ["dna", "rna", "nucleotide", "gene", "genome", "sequenc", "molecular biology", "genetic", "helix", "chromosome", "crispr", "protein", "double helix", "base pair"],
    "music_history": ["music", "composer", "symphony", "sonata", "concerto", "orchestra", "baroque", "classical", "romantic", "jazz", "piano", "violin", "opera", "harmony", "melody", "bach", "mozart", "beethoven", "haydn"]
}

DEST_DIRS = {
    "LLM": os.path.join(SOURCE_DIR, "LLM"),
    "trapped_ion_and_qc": os.path.join(SOURCE_DIR, "trapped_ion_and_qc"),
    "black_hole": os.path.join(SOURCE_DIR, "black_hole"),
    "DNA": os.path.join(SOURCE_DIR, "DNA"),
    "music_history": os.path.join(SOURCE_DIR, "music_history")
}

# Ensure destination directories exist
for d in DEST_DIRS.values():
    os.makedirs(d, exist_ok=True)

def extract_text_from_pdf(filepath):
    text = ""
    try:
        with open(filepath, 'rb') as f:
            reader = PyPDF2.PdfReader(f)
            # Read first 2 pages (usually enough for abstract/intro)
            for i in range(min(len(reader.pages), 3)):
                page = reader.pages[i]
                extracted = page.extract_text()
                if extracted:
                    text += extracted + " "
    except Exception as e:
        print(f"Error reading PDF {filepath}: {e}")
    return text

def extract_text_from_docx_pptx(filepath):
    text = ""
    try:
        if not zipfile.is_zipfile(filepath):
            return ""

        with zipfile.ZipFile(filepath, 'r') as z:
            xml_content = ""
            if filepath.endswith('.docx'):
                if 'word/document.xml' in z.namelist():
                    xml_content = z.read('word/document.xml').decode('utf-8')
            elif filepath.endswith('.pptx'):
                # Try to read first few slides
                for i in range(1, 5):
                    slide_name = f'ppt/slides/slide{i}.xml'
                    if slide_name in z.namelist():
                        xml_content += z.read(slide_name).decode('utf-8') + " "

            # Simple XML tag stripping
            text = re.sub('<[^<]+?>', ' ', xml_content)
    except Exception as e:
        print(f"Error reading DOCX/PPTX {filepath}: {e}")
    return text

def classify_text(text):
    text_lower = text.lower()
    scores = {cat: 0 for cat in CATEGORIES}

    for cat, keywords in CATEGORIES.items():
        for kw in keywords:
            if kw in text_lower:
                scores[cat] += text_lower.count(kw)

    # Return category with max score, default to music_history if all 0 (as per instructions "if does not fit... last one" - wait, instructions say "does not fit into any other 4 folders, it should fit into the last one". So music_history is the fallback? Or implies it's the 5th category.)
    # Actually, let's look at scores.
    best_cat = max(scores, key=scores.get)
    if scores[best_cat] == 0:
        return "music_history" # Fallback
    return best_cat

def main():
    files = [f for f in os.listdir(SOURCE_DIR) if os.path.isfile(os.path.join(SOURCE_DIR, f))]

    for filename in files:
        filepath = os.path.join(SOURCE_DIR, filename)

        # Skip if it is this script or similar
        if filename == "organize_papers.py" or filename.endswith(".md"):
            continue

        text = ""
        if filename.lower().endswith('.pdf'):
            text = extract_text_from_pdf(filepath)
        elif filename.lower().endswith('.docx') or filename.lower().endswith('.pptx'):
            text = extract_text_from_docx_pptx(filepath)

        if not text:
            print(f"Could not extract text from {filename}, skipping or moving to fallback.")
            category = "music_history"
        else:
            category = classify_text(text)

        print(f"File: {filename} -> Category: {category}")

        dest_path = os.path.join(DEST_DIRS[category], filename)
        shutil.move(filepath, dest_path)

if __name__ == "__main__":
    main()

